    (131, 'GERENCIA DE LA DEFENSORA NACIONAL DE LOS DERECHOS DE LA MUJER', 'SEDE INAMUJER', 'ZULIA', '04165683032/04269006665', 'nailaatencio2@gmail.com', NULL, 21, 310, NULL, '2026-06-19 19:01:01.273239'),
